{"path": "/app/shipclient/retry.py", "content": """"Retry policy for outbound HTTP calls made through shipclient."""

import re
from datetime import datetime, timezone

# Defaults from the HTTP client standard (v3) and rate limit handling.
DEFAULT_MAX_ATTEMPTS = 5
DEFAULT_BACKOFF_CAP = 8.0
DEFAULT_MAX_RETRY_AFTER = 30.0
FIRST_DELAY = 0.25

RETRYABLE_STATUSES = {429, 502, 503, 504}
IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
NON_IDEMPOTENT_METHODS = {"POST", "PATCH"}

# Current retry profiles: service -> (attempts, backoff cap, max Retry-After).
RETRY_PROFILES = {
    "payments": (3, 1.0, 30.0),
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "ledger-export": (4, 8.0, 10.0),
    "auth": (6, 6.0, 20.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

_MONTHS = {
    "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4, "May": 5, "Jun": 6,
    "Jul": 7, "Aug": 8, "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12,
}
_HTTP_DATE = re.compile(
    r"(Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\d{2}) ([A-Z][a-z]{2}) (\d{4}) "
    r"(\d{2}):(\d{2}):(\d{2}) GMT",
    re.ASCII,
)
_SECONDS = re.compile(r"\d+", re.ASCII)


def _header(headers, name):
    if not headers:
        return None
    name = name.lower()
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == name:
            return value
    return None


def _retry_after_seconds(value, now):
    """Parsed Retry-After wait in seconds, or None if absent or malformed."""
    if not isinstance(value, str):
        return None
    value = value.strip()
    if _SECONDS.fullmatch(value):
        return float(int(value))
    m = _HTTP_DATE.fullmatch(value)
    if not m:
        return None
    _, day, mon, year, hh, mm, ss = m.groups()
    if mon not in _MONTHS:
        return None
    try:
        when = datetime(
            int(year), _MONTHS[mon], int(day), int(hh), int(mm), int(ss),
            tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    # Is the failure retryable?
    if status is not None and status not in RETRYABLE_STATUSES:
        return None

    # Is the request safe to repeat?
    method = (method or "").upper()
    if method in NON_IDEMPOTENT_METHODS:
        key = _header(request_headers, "Idempotency-Key")
        if not isinstance(key, str) or not key.strip():
            return None
    elif method not in IDEMPOTENT_METHODS:
        return None

    # Per-service settings.
    max_attempts = DEFAULT_MAX_ATTEMPTS
    cap = DEFAULT_BACKOFF_CAP
    max_retry_after = DEFAULT_MAX_RETRY_AFTER
    service = _header(request_headers, "X-Service")
    if isinstance(service, str):
        profile = RETRY_PROFILES.get(service.lower())
        if profile:
            max_attempts, cap, max_retry_after = profile

    if attempt >= max_attempts:
        return None

    delay = min(FIRST_DELAY * (2 ** (attempt - 1)), cap)

    if status in (429, 503):
        wait = _retry_after_seconds(_header(response_headers, "Retry-After"), now)
        if wait is not None:
            if wait > max_retry_after:
                return None
            delay = max(delay, wait)

    return float(delay)
